  duskLit = mix(duskLit, min(bottomCol * 1.15, vec3(1.0)), 0.18);
  duskLit *= mix(0.92, 1.0, sunward);
  brightEdgeColor = mix(brightEdgeColor, duskLit, dusk * vivid);
